// dorado_baseboard_machine -- the machine with its external connections resolved, so
// that a testbench only has to provide a clock.
//
// NO CLOCK IS INJECTED. The machine generates its own: the VCO is
// substituted for a fabric-clock divider (cell_MPQ3303 -- an analog
// oscillator has no digital model), and everything after it is the
// BaseBoard's own logic, dividing that into StartClockPulse' and
// EndClockPulse and fanning them out to every slot. CLK.InBase is
// looped back from CLK.OutBase', which is what the backplane does.
//
// EVERY OTHER INPUT IS TIED LOW, and that is a physical claim, not a
// convenience: an unterminated MECL 10K input sits at VEE, which reads
// as 0. So this is the machine with no cables attached. Mind that many
// of these signals are ACTIVE LOW (the names ending in ') and are
// therefore ASSERTED in this state -- a disk or ethernet model has to
// drive them properly before anything using them means much.
//
// probe_val exposes 68 signals, 32 at a time;
// dorado_baseboard.probes lists which bit is which.
module dorado_baseboard_machine (
    input  wire        sys_clk,
    input  wire [15:0] probe_sel,
    output wire [31:0] probe_val,
    output wire [15:0] probe_words
);

  wire ACPI_0;
  wire ACPI_1;
  wire ACPI_2;
  wire ACPI_3;
  wire ACPI_4;
  wire ACPIGnd_0;
  wire ACPIGnd_1;
  wire ACPIGnd_2;
  wire ACPIGnd_3;
  wire ACPIGnd_4;
  wire BootMC_p_;
