  wire CLK_ms0Odd_p_;
  wire CLK_ms1Even_p_;
  wire CLK_ms1Odd_p_;
  wire CLK_ms2Even_p_;
  wire CLK_ms2Odd_p_;
  wire CLK_ms3Even_p_;
  wire CLK_ms3Odd_p_;
  wire CLK_mx_p_;
  wire CLK_ph_p_;
  wire CLK_pl_p_;
  wire CPAddr_0_p_;
  wire CPAddr_1_p_;
  wire CPAddr_2_p_;
  wire CPOut_0;
  wire CPOut_1;
  wire CPOut_2;
  wire CPOut_3;
  wire CPOut_4;
  wire CPOut_5;
  wire CPOut_6;
  wire CPOut_7;
  wire CPOut_8;
  wire CPStrb_p_;
  wire DMuxClk;
  wire DMuxData;
  wire IOReset;
  wire KeyboardData;
  wire Pendulum;
  wire RfshPeriod;
  wire Sequence0_p_;
  wire SetRun;
  wire SetRunRfsh;
  wire SetSS_p_;
  wire SkipWait_p_;
  wire StartClockPulse;
