    UseDMD,
    TurnOnPwr_p_,
    TurnOnLED_p_,
    TurnOnDisk_p_,
    TurnOff2v,
    TempRef,
    TTLIOReset_p_,
    StartClockPulse,
    SkipWait_p_,
    SetSS_p_,
    SetRunRfsh,
    SetRun,
    Sequence0_p_,
    RfshPeriod,
    Pendulum,
    KeyboardData,
    IOReset,
    DMuxData,
    DMuxClk,
    CPStrb_p_,
    CPOut_8,
    CPOut_7,
    CPOut_6,
    CPOut_5,
    CPOut_4,
    CPOut_3,
    CPOut_2,
    CPOut_1,
    CPOut_0,
    CPAddr_2_p_,
    CPAddr_1_p_,
    CPAddr_0_p_,
    CLK_pl_p_,
    CLK_ph_p_,
    CLK_mx_p_,
    CLK_ms3Odd_p_,
    CLK_ms3Even_p_,
    CLK_ms2Odd_p_,
    CLK_ms2Even_p_,
    CLK_ms1Odd_p_,
    CLK_ms1Even_p_,
    CLK_ms0Odd_p_,
    CLK_ms0Even_p_,
    CLK_md_p_,
    CLK_mc_p_,
    CLK_io24_p_,
    CLK_io23_p_,
    CLK_io22_p_,
    CLK_io21_p_,
    CLK_io20_p_,
    CLK_ifu_p_,
    CLK_display_p_,
    CLK_disk_p_,
    CLK_cb_p_,
    CLK_ca_p_,
    CLK_OutBase_p_,
    BootNO,
    BootMC_p_,
    ACPIGnd_4,
    ACPIGnd_3,
    ACPIGnd_2,
    ACPIGnd_1,
    ACPIGnd_0,
    ACPI_4,
    ACPI_3,
    ACPI_2,
    ACPI_1,
