  dorado_baseboard u_machine (
    .sys_clk(sys_clk),
    .ACPABus_0_p_(1'b0),
    .ACPABus_1_p_(1'b0),
    .ACPABus_2_p_(1'b0),
    .ACPBus_0_p_(1'b0),
    .ACPBus_1_p_(1'b0),
    .ACPBus_2_p_(1'b0),
    .ACPBus_3_p_(1'b0),
    .ACPBus_4_p_(1'b0),
    .ACPBus_5_p_(1'b0),
    .ACPBus_6_p_(1'b0),
    .ACPBus_7_p_(1'b0),
    .ACPBus_8_p_(1'b0),
    .ACPGnd_00(1'b0),
    .ACPGnd_01(1'b0),
    .ACPGnd_02(1'b0),
    .ACPGnd_03(1'b0),
    .ACPGnd_04(1'b0),
    .ACPGnd_05(1'b0),
    .ACPGnd_06(1'b0),
    .ACPGnd_07(1'b0),
    .ACPGnd_08(1'b0),
    .ACPGnd_09(1'b0),
    .ACPGnd_10(1'b0),
    .ACPGnd_11(1'b0),
    .ACPGnd_12(1'b0),
    .ACPI_0(ACPI_0),
    .ACPI_1(ACPI_1),
    .ACPI_2(ACPI_2),
    .ACPI_3(ACPI_3),
    .ACPI_4(ACPI_4),
    .ACPIGnd_0(ACPIGnd_0),
    .ACPIGnd_1(ACPIGnd_1),
    .ACPIGnd_2(ACPIGnd_2),
    .ACPIGnd_3(ACPIGnd_3),
    .ACPIGnd_4(ACPIGnd_4),
    .ACPStrb_p_(1'b0),
    .BootMC_p_(BootMC_p_),
    .BootNO(BootNO),
    .CBTempSense(1'b0),
    .CICC__m_SS(1'b0),
    .CICC_EOS(1'b0),
    .CIDD__m_SS(1'b0),
    .CIDD_EOS(1'b0),
    .CIEE__m_SS(1'b0),
    .CIEE_EOS(1'b0),
    .CITT__pl_SS(1'b0),
    .CITT_EOS(1'b0),
    .CLK_InBase(CLK_OutBase_p_),
    .CLK_OutBase_p_(CLK_OutBase_p_),
    .CLK_ca_p_(CLK_ca_p_),
    .CLK_cb_p_(CLK_cb_p_),
    .CLK_disk_p_(CLK_disk_p_),
    .CLK_display_p_(CLK_display_p_),
    .CLK_ifu_p_(CLK_ifu_p_),
    .CLK_io20_p_(CLK_io20_p_),
    .CLK_io21_p_(CLK_io21_p_),
    .CLK_io22_p_(CLK_io22_p_),
    .CLK_io23_p_(CLK_io23_p_),
    .CLK_io24_p_(CLK_io24_p_),
    .CLK_mc_p_(CLK_mc_p_),
    .CLK_md_p_(CLK_md_p_),
    .CLK_ms0Even_p_(CLK_ms0Even_p_),
    .CLK_ms0Odd_p_(CLK_ms0Odd_p_),
    .CLK_ms1Even_p_(CLK_ms1Even_p_),
    .CLK_ms1Odd_p_(CLK_ms1Odd_p_),
    .CLK_ms2Even_p_(CLK_ms2Even_p_),
    .CLK_ms2Odd_p_(CLK_ms2Odd_p_),
    .CLK_ms3Even_p_(CLK_ms3Even_p_),
    .CLK_ms3Odd_p_(CLK_ms3Odd_p_),
    .CLK_mx_p_(CLK_mx_p_),
    .CLK_ph_p_(CLK_ph_p_),
    .CLK_pl_p_(CLK_pl_p_),
    .CPAddr_0_p_(CPAddr_0_p_),
    .CPAddr_1_p_(CPAddr_1_p_),
    .CPAddr_2_p_(CPAddr_2_p_),
    .CPIn_0(1'b0),
    .CPIn_1(1'b0),
    .CPIn_2(1'b0),
    .CPIn_3(1'b0),
    .CPOut_0(CPOut_0),
    .CPOut_1(CPOut_1),
    .CPOut_2(CPOut_2),
    .CPOut_3(CPOut_3),
    .CPOut_4(CPOut_4),
    .CPOut_5(CPOut_5),
    .CPOut_6(CPOut_6),
    .CPOut_7(CPOut_7),
    .CPOut_8(CPOut_8),
    .CPStrb_p_(CPStrb_p_),
    .Collision(1'b0),
    .DMuxClk(DMuxClk),
    .DMuxData(DMuxData),
    .DiskOnRet(1'b0),
    .IOReset(IOReset),
    .KeyboardData(KeyboardData),
    .LEDOnRet(1'b0),
    .OISData(1'b0),
    .OISData_p_(1'b0),
    .Pendulum(Pendulum),
    .PwrOnRet(1'b0),
    .RcvData(1'b0),
    .RfshPeriod(RfshPeriod),
    .Sequence0_p_(Sequence0_p_),
    .Serial_1(1'b0),
    .Serial_10(1'b0),
    .Serial_100(1'b0),
    .Serial_2(1'b0),
    .Serial_20(1'b0),
    .Serial_200(1'b0),
    .Serial_4(1'b0),
    .Serial_40(1'b0),
    .SetRun(SetRun),
    .SetRunRfsh(SetRunRfsh),
